function MemoryTimeline(props: { readonly refreshKey: number }): ReactNode {
  const t = currentLocale()
  const [entries, setEntries] = useState<MemoryEntry[] | null | undefined>(undefined)

  useEffect(() => {
    void (async () => {
      const result = await callApi<{ available: boolean; memories: MemoryEntry[] | null }>('memories')
      setEntries(result.ok && result.available ? result.memories : null)
    })()
  }, [props.refreshKey])

  if (entries === undefined) return null
  if (entries === null) return <div className={styles.hint}>{t['memory.timelineUnavailable']}</div>
  const grouped: Array<[string, MemoryEntry[]]> = []
  {
    const byDay = new Map<string, MemoryEntry[]>()
    for (const entry of entries) {
      const day = entry.created.slice(0, 10) || '—'
      const bucket = byDay.get(day)
      if (bucket === undefined) byDay.set(day, [entry])
      else bucket.push(entry)
    }
    grouped.push(...byDay.entries())
  }
  return (
    <>
      <div className={styles.sectionTitle}>🗂 {format(t['memory.timeline'], { n: entries.length })}</div>
      {entries.length === 0 && <div className={styles.meta}>{t['memory.empty']}</div>}
      {grouped.map(([day, dayEntries]) => (
        <div key={day} className={styles.dayGroup}>
          <div className={styles.dayLabel}>{day}</div>
          {dayEntries.map(entry => <MemoryCard key={entry.path} entry={entry} />)}
        </div>
      ))}
    </>
  )
}

function MemoryView(props: { readonly onSaved: () => void }): ReactNode {
  const t = currentLocale()
  const [query, setQuery] = useState('')
  const [hits, setHits] = useState<SearchHit[] | null>(null)
  const [busy, setBusy] = useState(false)
  const [title, setTitle] = useState('')
  const [text, setText] = useState('')
  const [tags, setTags] = useState('')
  const [saveState, setSaveState] = useState<'idle' | 'busy' | 'saved'>('idle')
  const [savedPath, setSavedPath] = useState('')
  const [refreshKey, setRefreshKey] = useState(0)
  const err = useApiError()

  const run = useCallback(async () => {
    if (query.trim() === '') return
    setBusy(true)
    err.setError(null)
    const result = await callApi<{ hits: SearchHit[] }>('search', { query, k: 50, tag: 'memory' })
    setBusy(false)
    if (result.ok) setHits(result.hits)
    else {
      err.setError(result.error)
      setHits(null)
    }
  }, [query])

  const save = useCallback(async () => {
    if (text.trim() === '') return
    setSaveState('busy')
    err.setError(null)
    const result = await callApi<{ result: string }>('remember', {
      text,
      ...(title.trim() === '' ? {} : { title: title.trim() }),
      ...(tags.trim() === '' ? {} : { tags: tags.split(/[,，]/).map(tag => tag.trim()).filter(tag => tag !== '') }),
    })
    if (result.ok) {
      setSaveState('saved')
      setSavedPath(result.result)
      setText('')
      setTitle('')
      setTags('')
      setRefreshKey(key => key + 1)
      props.onSaved()
    } else {
      setSaveState('idle')
      err.setError(result.error)
    }
  }, [text, title, tags, props])

  const grouped = useMemo(() => {
    if (hits === null) return []
    const byDay = new Map<string, SearchHit[]>()
    for (const hit of hits) {
      const day = hit.memoryTime?.slice(0, 10) ?? '—'
      const bucket = byDay.get(day)
      if (bucket === undefined) byDay.set(day, [hit])
      else bucket.push(hit)
    }
    return [...byDay.entries()].sort((a, b) => b[0].localeCompare(a[0]))
  }, [hits])

  return (
    <div className={styles.view}>
      <MemoryTimeline refreshKey={refreshKey} />

      <div className={styles.sectionTitle}>🔍 {t['view.memory']}</div>
      <div className={styles.formRow}>
        <input
          className={styles.input}
          value={query}
          placeholder={t['memory.placeholder']}
          onChange={event => setQuery(event.target.value)}
          onKeyDown={event => {
            if (event.key === 'Enter') void run()
          }}
        />
        <button type="button" className={styles.button} disabled={busy || query.trim() === ''} onClick={() => void run()}>
          {busy ? t['search.searching'] : t['search.button']}
        </button>
      </div>
      {err.render()}
      {hits !== null && hits.length === 0 && <div className={styles.meta}>{t['memory.empty']}</div>}
      {grouped.map(([day, dayHits]) => (
        <div key={day} className={styles.dayGroup}>
          <div className={styles.dayLabel}>{day}</div>
          {dayHits.map(hit => (
            <div key={`${hit.index}-${hit.source}`} className={styles.memoryCard}>
              <div className={styles.memoryTime}>{hit.memoryTime ?? ''}</div>
              <pre className={styles.hitText}>{hit.text}</pre>
            </div>
          ))}
        </div>
      ))}
      <div className={styles.hint}>{t['memory.hint']}</div>

      <div className={styles.sectionTitle}>✍️ {t['memory.submit']}</div>
      <input className={styles.input} value={title} placeholder={t['memory.title']} onChange={event => setTitle(event.target.value)} />
      <textarea
        className={styles.textarea}
        rows={3}
        value={text}
        placeholder={t['memory.text']}
        onChange={event => setText(event.target.value)}
      />
      <input className={styles.input} value={tags} placeholder={t['memory.tags']} onChange={event => setTags(event.target.value)} />
      <div className={styles.formRow}>
        <button type="button" className={styles.button} disabled={saveState === 'busy' || text.trim() === ''} onClick={() => void save()}>
          {saveState === 'busy' ? t['memory.saving'] : t['memory.submit']}
        </button>
        {saveState === 'saved' && (
          <span className={styles.saved} title={savedPath}>✓ {t['memory.saved']}</span>
        )}
      </div>
    </div>
  )
}

/** Which AI coding tools are installed on this machine, and what each holds. */
function HarnessView(): ReactNode {
  const t = currentLocale()
  const [rows, setRows] = useState<HarnessRow[] | null | undefined>(undefined)
  const [expanded, setExpanded] = useState<string | null>(null)

  useEffect(() => {
    void (async () => {
      const result = await callApi<{ available: boolean; harness: HarnessRow[] }>('harness')
      setRows(result.ok ? result.harness : null)
    })()
  }, [])

  if (rows === undefined) {
    return <div className={styles.view}><div className={styles.meta}>{t['conn.checking']}</div></div>
  }
  if (rows === null) {
    return <div className={styles.view}><div className={styles.errorBox}>{t['harness.error']}</div></div>
  }
  if (rows.length === 0) {
    return (
      <div className={styles.view}>
        <div className={styles.meta}>{t['harness.empty']}</div>
        <div className={styles.hint}>{t['harness.emptyHint']}</div>
      </div>
    )
  }
  const totalFiles = rows.reduce((sum, row) => sum + row.files, 0)
  const totalChunks = rows.reduce((sum, row) => sum + row.chunks, 0)
  return (
    <div className={styles.view}>
      <div className={styles.hint}>{t['harness.hint']}</div>
      <div className={styles.meta}>
        {format(t['harness.totals'], { tools: rows.length, files: totalFiles, chunks: totalChunks })}
      </div>
      {rows.map(row => (
        <div key={row.name} className={styles.memoryCard}>
          <div className={styles.memoryHead}>
            <span className={styles.memoryTitle}>
              {/* an icon field that is a filename means loci has a logo file;
                  this tab cannot serve it, so show the name alone rather than
                  printing "zcode-logo.png" */}
              {isImageIcon(row.icon) ? '' : `${row.icon} `}{row.display}
            </span>
            <span className={styles.memoryTime}>{row.type}</span>
          </div>
          <div className={styles.memoryTags}>
            <span className={styles.memoryTag}>
              {format(t['harness.files'], { n: row.files })}
            </span>
            <span className={styles.memoryTag}>
              {format(t['harness.chunks'], { n: row.chunks })}
            </span>
            {row.lastUpdated !== '' && (
              <span className={styles.memoryTag}>{row.lastUpdated}</span>
            )}
            {row.missingRoots > 0 && (
              <span className={styles.memoryTag} title={t['harness.missingRootsHint']}>
                {format(t['harness.missingRoots'], { n: row.missingRoots })}
              </span>
            )}
          </div>
          {expanded === row.name && row.summaryStatus !== '' && (
            <div className={styles.meta}>{format(t['harness.digest'], { status: row.summaryStatus })}</div>
          )}
          <div className={styles.formRow}>
            <button
              type="button"
              className={styles.linkButton}
              onClick={() => setExpanded(expanded === row.name ? null : row.name)}
            >
              {expanded === row.name ? t['memory.fold'] : t['harness.detail']}
            </button>
          </div>
        </div>
      ))}
    </div>
  )
}

function isImageIcon(icon: string): boolean {
  // a logo filename means the file exists somewhere; the tab cannot serve it,
  // so fall back to the tool's first letter rather than printing "zcode-logo.png"
  return /\.(png|svg|jpe?g|gif|webp)$/i.test(icon)
}

function GraphView(): ReactNode {
  const t = currentLocale()
  // Two shapes of "graph" live here, because they answer different questions:
  // SPO relations come from an LLM pass over the notes (needs `loci graph
  // build`), while note links come straight from `[[wikilinks]]` and are
  // always available.
  const [mode, setMode] = useState<'relations' | 'links'>('links')
  return (
    <div className={styles.view}>
      <div className={styles.tabs} role="tablist">
        <button
          type="button"
          role="tab"
          aria-selected={mode === 'links'}
          className={`${styles.tabButton} ${mode === 'links' ? styles.tabActive : ''}`}
          onClick={() => setMode('links')}
        >
          {t['graph.mode.links']}
        </button>
        <button
          type="button"
          role="tab"
          aria-selected={mode === 'relations'}
          className={`${styles.tabButton} ${mode === 'relations' ? styles.tabActive : ''}`}
          onClick={() => setMode('relations')}
        >
          {t['graph.mode.relations']}
        </button>
      </div>
      {mode === 'links' ? <WikiGraphView /> : <RelationGraphView />}
    </div>
  )
}

/** `[[wikilink]]` graph from loci's `/graph` — no LLM, no build step. */
function WikiGraphView(): ReactNode {
  const t = currentLocale()
  const [graph, setGraph] = useState<WikiGraph | null | undefined>(undefined)
  const [filter, setFilter] = useState('')
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    void (async () => {
      const result = await callApi<{ available: boolean; graph: WikiGraph }>('wikilinks')
      setGraph(result.ok ? result.graph : null)
    })()
  }, [])

  if (graph === undefined) {
    return <div className={styles.meta}>{t['conn.checking']}</div>
  }
  if (graph === null) {
    return <div className={styles.errorBox}>{t['graph.error']}</div>
  }
  if (graph.nodes.length === 0) {
    return (
      <>
        <div className={styles.meta}>{t['links.empty']}</div>
        <div className={styles.hint}>{t['links.emptyHint']}</div>
      </>
    )
  }

  // A link target is written as a bare name; resolve it against note stems the
  // way Obsidian does. Two notes with the same name stay unresolved (ambiguous
  // is not a guess) and show up as broken links instead.
  const byStem = new Map<string, WikiNode | null>()
  for (const node of graph.nodes) {
    const key = node.name.toLowerCase()
    byStem.set(key, byStem.has(key) ? null : node)
  }
  const pathOf = new Map(graph.nodes.map(node => [node.path, node]))
  const degree = new Map<string, { out: number; in: number }>()
  const bump = (path: string, side: 'out' | 'in'): void => {
    const entry = degree.get(path) ?? { out: 0, in: 0 }
    entry[side] += 1
    degree.set(path, entry)
  }
  let broken = 0
  for (const link of graph.links) {
    const target = byStem.get(link.to.split('/').pop()?.replace(/\.md$/i, '').toLowerCase() ?? '')
    if (target === undefined || target === null) { broken += 1; continue }
    bump(link.from, 'out')
    bump(target.path, 'in')
  }

  const needle = filter.trim().toLowerCase()
  const shown = graph.nodes
    .filter(node => needle === '' || node.path.toLowerCase().includes(needle))
    .sort((a, b) => {
      const da = degree.get(a.path) ?? { out: 0, in: 0 }
      const db = degree.get(b.path) ?? { out: 0, in: 0 }
      return (db.out + db.in) - (da.out + da.in) || a.name.localeCompare(b.name)
    })

  const related = selected !== null
    ? graph.links.filter(link => {
      if (link.from === selected) return true
      const target = byStem.get(link.to.split('/').pop()?.replace(/\.md$/i, '').toLowerCase() ?? '')
      return target?.path === selected
    })
    : []

  return (
    <>
      <div className={styles.hint}>{t['links.hint']}</div>
      <div className={styles.meta}>
        {format(t['links.stats'], {
          n: graph.nodes.length,
          l: graph.links.length,
          b: broken,
        })}
      </div>
      <div className={styles.formRow}>
        <input
          className={styles.input}
          value={filter}
          placeholder={t['links.filter']}
          onChange={event => setFilter(event.target.value)}
        />
      </div>
      {selected !== null && (
        <div className={styles.formRow}>
          <span className={styles.graphSelected}>
            {format(t['links.related'], { name: pathOf.get(selected)?.name ?? selected })}
          </span>
          <button type="button" className={styles.linkButton} onClick={() => setSelected(null)}>
            {t['graph.clearFilter']}
          </button>
        </div>
      )}
      <div className={styles.sectionTitle}>{t['links.notes']}</div>
      <div className={styles.graphChips}>
        {shown.map(node => {
          const d = degree.get(node.path) ?? { out: 0, in: 0 }
          return (
            <button
              key={node.path}
              type="button"
              title={format(t['links.degree'], { out: d.out, in: d.in, c: node.chunks })}
              className={`${styles.graphChip} ${selected === node.path ? styles.graphChipActive : ''}`}
              onClick={() => setSelected(selected === node.path ? null : node.path)}
            >
              {node.name}
              <span className={styles.graphChipDegree}>{d.out + d.in}</span>
            </button>
          )
        })}
      </div>
      {selected !== null && (
        <>
          <div className={styles.sectionTitle}>{t['links.connections']}</div>
          {related.length === 0 && <div className={styles.meta}>{t['links.isolated']}</div>}
          {related.map((link, i) => (
            <div key={`${link.from}-${link.to}-${i}`} className={styles.sourceRow}>
              <span className={styles.mono}>{pathOf.get(link.from)?.name ?? link.from}</span>
              <span className={styles.graphPredicate}>→</span>
              <span className={styles.mono}>{link.to}</span>
            </div>
          ))}
        </>
      )}
    </>
  )
}

/** SPO relations from `graph.json` (`loci graph build`). */
function RelationGraphView(): ReactNode {
  const t = currentLocale()
  const [graph, setGraph] = useState<GraphData | null | undefined>(undefined)
  const [filter, setFilter] = useState('')
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    void (async () => {
      const result = await callApi<{ available: boolean; graph: GraphData | null }>('graph')
      setGraph(result.ok && result.available ? result.graph : null)
    })()
  }, [])

  if (graph === undefined) {
    return <div className={styles.meta}>{t['conn.checking']}</div>
  }
  if (graph === null) {
    return (
      <>
        <div className={styles.meta}>{t['graph.unavailable']}</div>
        <div className={styles.hint}>{t['graph.unavailableHint']}</div>
      </>
    )
  }
  const needle = filter.trim().toLowerCase()
  const shownEntities = needle === '' ? graph.entities : graph.entities.filter(entity => entity.name.toLowerCase().includes(needle))
  const shownEdges = selected !== null ? graph.edges.filter(edge => edge.s === selected || edge.o === selected) : graph.edges
  return (
    <>
      <div className={styles.hint}>{t['graph.hint']}</div>
      <div className={styles.meta}>{format(t['graph.stats'], { e: graph.entities.length, r: graph.edges.length, f: graph.files })}</div>
      {selected !== null && (
        <div className={styles.formRow}>
          <span className={styles.graphSelected}>{format(t['graph.related'], { name: selected })}</span>
          <button type="button" className={styles.linkButton} onClick={() => setSelected(null)}>{t['graph.clearFilter']}</button>
        </div>
      )}
      <div className={styles.formRow}>
        <input
          className={styles.input}
          value={filter}
          placeholder={t['graph.filter']}
          onChange={event => setFilter(event.target.value)}
        />
      </div>
      <div className={styles.sectionTitle}>{t['graph.entities']}</div>
      <div className={styles.graphChips}>
        {shownEntities.map(entity => (
          <button
            key={entity.name}
            type="button"
            title={format(t['graph.hub'], { n: entity.degree })}
            className={`${styles.graphChip} ${selected === entity.name ? styles.graphChipActive : ''}`}
            onClick={() => setSelected(selected === entity.name ? null : entity.name)}
          >
            {entity.name}
            <span className={styles.graphChipDegree}>{entity.degree}</span>
          </button>
        ))}
      </div>
      <div className={styles.sectionTitle}>{t['graph.relations']}</div>
      <div>
        {shownEdges.map((edge, i) => (
          <div key={`${edge.s}-${edge.p}-${edge.o}-${i}`} className={styles.graphEdge}>
            <button type="button" className={styles.graphTerm} onClick={() => setSelected(edge.s)}>{edge.s}</button>
            <span className={styles.graphPredicate} title={t['graph.predicate']}>{edge.p}</span>
            <button type="button" className={styles.graphTerm} onClick={() => setSelected(edge.o)}>{edge.o}</button>
          </div>
        ))}
      </div>
    </>
  )
}

/** Client-side copy of the package version (keep in sync on release). */
const APP_VERSION = '0.3.0'
const REPO_URL = 'https://github.com/IvenKooLab/loci-dsh'

function StatusView(): ReactNode {
  const t = currentLocale()
  const [state, setState] = useState<{ ping: { baseUrl: string; tokenSet: boolean; health: string }; stats: ParsedStats } | null>(null)
  const err = useApiError()

  useEffect(() => {
    void (async () => {
      const ping = await callApi<{ baseUrl: string; tokenSet: boolean; health: string }>('ping')
      if (!ping.ok) {
        err.setError(ping.error)
        return
      }
      const stats = await callApi<{ stats: ParsedStats }>('stats')
      if (!stats.ok) {
        err.setError(stats.error)
        return
      }
      setState({ ping, stats: stats.stats })
    })()
  }, [])

  if (err.error !== null) return <div className={styles.view}>{err.render()}</div>
  if (state === null) return <div className={styles.view}><div className={styles.meta}>{t['conn.checking']}</div></div>
  const { ping, stats } = state
  return (
    <div className={styles.view}>
      <dl className={styles.statusList}>
        <div className={styles.statusRow}><dt>{t['status.baseUrl']}</dt><dd className={styles.mono}>{ping.baseUrl}</dd></div>
        <div className={styles.statusRow}><dt>{t['status.token']}</dt><dd>{ping.tokenSet ? t['status.tokenSet'] : t['status.tokenMissing']}</dd></div>
        <div className={styles.statusRow}><dt>{t['status.store']}</dt><dd className={styles.mono}>{stats.storePath} · {format(t['status.chunks'], { n: stats.chunks })}</dd></div>
        <div className={styles.statusRow}><dt>{t['status.models']}</dt><dd className={styles.mono}>{stats.embedModel} / {stats.llmModel}</dd></div>
        <div className={styles.statusRow}><dt>{t['status.retrieval']}</dt><dd className={styles.mono}>{stats.retrieval}</dd></div>
      </dl>
      <div className={styles.sectionTitle}>{format(t['status.sources'], { n: stats.sources.length })}</div>
      {stats.empty
        ? <div className={styles.hint}>{t['status.empty']}</div>
        : stats.sources.map(source => (
            <div key={source.path} className={styles.sourceRow} title={source.path}>
              <span className={styles.mono}>{basename(source.path)}</span>
              <span className={styles.sourceChunks}>{source.chunks}</span>
            </div>
          ))}
      <div className={styles.footer}>
        <span className={styles.footerVersion}>loci-dsh v{APP_VERSION}</span>
        <a className={styles.footerStar} href={REPO_URL} target="_blank" rel="noreferrer">{t['status.star']}</a>
      </div>
    </div>
  )
}
